class Solution {
    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        return helper(l1, l2, 0);
    }
    private ListNode helper(ListNode n1, ListNode n2, int carry) {
        if (n1 == null && n2 == null && carry == 0) return null;
        int x = (n1 != null) ? n1.val : 0;
        int y = (n2 != null) ? n2.val : 0;
        int s = x + y + carry;
        ListNode node = new ListNode(s % 10);
        ListNode nxt1 = (n1 != null) ? n1.next : null;
        ListNode nxt2 = (n2 != null) ? n2.next : null;
        node.next = helper(nxt1, nxt2, s / 10);
        return node;
    }
}

